c1, c2 = st.columns([1.15, 1])

with c1:
    st.markdown('<p class="panel-title">Evolución mensual</p><p class="panel-sub">Gasto total por mes, desglosado por área</p>', unsafe_allow_html=True)
    g = filtered.groupby(["mes_key", "tipo"])["total"].sum().unstack(fill_value=0.0)
    for t in TIPOS:
        if t not in g.columns:
            g[t] = 0.0
    g = g.sort_index()
    labels = [MONTH_NAMES[int(k[5:7])] for k in g.index]

    fig_trend = go.Figure()
    for t in TIPOS:
        fig_trend.add_bar(name=t, x=labels, y=g[t], marker_color=COLORS[t],
                           hovertemplate="%{x} · " + t + ": %{y:,.2f} €<extra></extra>")
    fig_trend.update_layout(
        barmode="stack", height=310,
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=dict(family="IBM Plex Mono, monospace", color=MUTED, size=11),
        legend=dict(orientation="h", yanchor="bottom", y=1.03, xanchor="right", x=1,
                    font=dict(family="Inter, sans-serif", size=11)),
        margin=dict(t=10, b=10, l=10, r=10),
        xaxis=dict(showgrid=False),
        yaxis=dict(showgrid=True, gridcolor=LINE_SOFT),
        hovermode="x unified",
    )
    st.plotly_chart(fig_trend, width="stretch", config={"displayModeBar": False})

with c2:
    st.markdown('<p class="panel-title">Distribución por área</p><p class="panel-sub">% del gasto filtrado</p>', unsafe_allow_html=True)
    values = [float(by_tipo.get(t, 0.0)) for t in TIPOS]
    colors_donut = [COLORS[t] for t in TIPOS]

    fig_donut = go.Figure(go.Pie(
        labels=TIPOS, values=values, hole=0.68,
        marker=dict(colors=colors_donut, line=dict(color=INK_2, width=3)),
        textinfo="none",
        hovertemplate="%{label}: %{value:,.2f} €<extra></extra>",
    ))
    fig_donut.update_layout(
        showlegend=False, height=210,
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        margin=dict(t=6, b=6, l=6, r=6),
    )
    st.plotly_chart(fig_donut, width="stretch", config={"displayModeBar": False})

    legend_html = ""
    for t, v, col in zip(TIPOS, values, colors_donut):
        p = (v / total * 100) if total else 0.0
        legend_html += (
            f'<div class="legend-row"><span class="t-dot" style="background:{col}"></span>'
            f'<span class="lname">{t}</span><span class="lval">{p:.1f}% · {eur(v)}</span></div>'
        )
    st.markdown(legend_html, unsafe_allow_html=True)

